from sage.all_cmdline import *   # import sage library

_sage_const_84 = Integer(84); _sage_const_8 = Integer(8); _sage_const_0p45 = RealNumber('0.45'); _sage_const_0x10001 = Integer(0x10001); _sage_const_1 = Integer(1); _sage_const_2 = Integer(2); _sage_const_0p03 = RealNumber('0.03'); _sage_const_0 = Integer(0)
from sage import *
from Crypto.Util.number import *

FLAG_BITS = _sage_const_84  * _sage_const_8  
BETA = _sage_const_0p45 

moduli = []     # p
cipher = []     # c
e = _sage_const_0x10001 

with open("./output.txt", "r") as f:
    for line in f:
        key, value = line.strip().split("=")

        if key == "p":
            moduli.append(Integer(value))
        elif key == "c":
            cipher.append(Integer(value))


residues = []

for p, c in zip(moduli, cipher):
    d = inverse_mod(e, p-_sage_const_1 )
    r = power_mod(c, d, p)
    residues.append(r)
    

N = prod(moduli)
R = CRT(residues, moduli)

PR = PolynomialRing(Zmod(N), names=('x',)); (x,) = PR._first_ngens(1)
f = x - R       # Coppersmith

roots = f.small_roots(
    X=_sage_const_2 **FLAG_BITS,
    beta=BETA,
    epsilon=_sage_const_0p03 
)

print(long_to_bytes(int(roots[_sage_const_0 ])))

